package android.util;public final class Base64 {public static final int NO_WRAP=2;public static byte[] encode(byte[] b,int flags){return java.util.Base64.getEncoder().encode(b);}public static String encodeToString(byte[] b,int flags){return java.util.Base64.getEncoder().encodeToString(b);}public static byte[] decode(String b,int flags){return java.util.Base64.getDecoder().decode(b);}}
